1	import { db } from "@/lib/db";
2	
3	/**
4	 * The ONE money helper for the marketing comparison surface. Every Nxeon price
5	 * shown on a /compare or competitor-alternative page is derived from a live
6	 * `db.plan` record through here — there is not a single hard-coded Nxeon plan
7	 * price on those pages, so a catalogue edit propagates automatically and the
8	 * comparison can never advertise a number checkout won't honour.
9	 */
10	export function money(cents: number): string {
11	  const v = cents / 100;
12	  return Number.isInteger(v) ? `$${v}` : `$${v.toFixed(2)}`;
13	}
14	
15	export type VpsPriceBand = {
16	  /** Cheapest active VPS plan. */
17	  fromCents: number;
18	  fromName: string;
19	  /** Dearest active VPS plan. */
20	  toCents: number;
21	  toName: string;
22	  /** "$6.49/mo" — the entry price, formatted. */
23	  fromLabel: string;
24	  /** "$32.99/mo" — the top price, formatted. */
25	  toLabel: string;
26	  /** "$6.49–$32.99/mo" — the full band, formatted for a single cell. */
27	  rangeLabel: string;
28	};
29	
30	/**
31	 * Reads the live Cloud VPS catalogue and returns the active price band, or
32	 * `null` when no plans are active (callers fall back to neutral, price-free
33	 * copy so a page never invents a figure). Pages that call this MUST set
34	 * `export const dynamic = "force-dynamic"` so the band tracks the DB.
35	 */
36	export async function getVpsPriceBand(): Promise<VpsPriceBand | null> {
37	  const plans = await db.plan.findMany({
38	    where: { active: true },
39	    orderBy: { priceCents: "asc" },
40	    select: { name: true, priceCents: true },
41	  });
42	  if (plans.length === 0) return null;
43	
44	  const from = plans[0];
45	  const to = plans[plans.length - 1];
46	  const fromLabel = `${money(from.priceCents)}/mo`;
47	  const toLabel = `${money(to.priceCents)}/mo`;
48	  const rangeLabel =
49	    from.priceCents === to.priceCents
50	      ? fromLabel
51	      : `${money(from.priceCents)}–${money(to.priceCents)}/mo`;
52	
53	  return {
54	    fromCents: from.priceCents,
55	    fromName: from.name,
56	    toCents: to.priceCents,
57	    toName: to.name,
58	    fromLabel,
59	    toLabel,
60	    rangeLabel,
61	  };
62	}
