4	/**
5	 * Marketing layout primitives (v2 redesign) — the single reuse layer every page
6	 * is built from, so the whole site reads as one designed thing.
7	 *
8	 *  - <Section>   full-width band with an alternating background "tone" and a
9	 *                consistent vertical rhythm + content rail. Replaces the ad-hoc
10	 *                `mx-auto max-w-6xl px-5 py-20` strings copy-pasted everywhere.
11	 *  - <PageHero>  the standard sub-page hero (eyebrow → title → sub → CTAs +
12	 *                optional visual). Replaces ~10 hand-rolled hero blocks.
13	 *  - <Eyebrow>   the uppercase tag above a heading.
14	 *  - <SectionTitle> heading + optional sub, centered or left.
15	 *
16	 * Colors and animations are the existing brand system (navy + violet/blue).
17	 */
18	
19	type Tone = "base" | "panel" | "deep" | "light";
20	type Size = "sm" | "md" | "lg";
21	
22	const TONE: Record<Tone, string> = {
23	  base: "",
24	  panel: "tone-panel",
25	  deep: "tone-deep",
26	  light: "tone-light",
27	};
28	const PAD: Record<Size, string> = {
29	  sm: "py-14 sm:py-16",
30	  md: "py-20 sm:py-24",
31	  lg: "py-24 sm:py-32",
32	};
33	
34	/** A full-width section band. `tone` alternates the background for rhythm. */
35	export function Section({
36	  children,
37	  tone = "base",
38	  size = "md",
39	  id,
40	  className = "",
41	}: {
42	  children: React.ReactNode;
43	  tone?: Tone;
44	  size?: Size;
45	  id?: string;
46	  className?: string;
47	}) {
48	  return (
49	    <section id={id} className={`relative ${TONE[tone]} ${PAD[size]} ${className}`}>
50	      <div className="rail">{children}</div>
51	    </section>
52	  );
53	}
54	
55	/** Uppercase eyebrow tag. `pill` gives it the bordered chip treatment. */
56	export function Eyebrow({ children, pill = false }: { children: React.ReactNode; pill?: boolean }) {
57	  return <span className={pill ? "eyebrow-pill" : "eyebrow"}>{children}</span>;
58	}
59	
60	/** Section heading block: eyebrow + title + optional sub. */
61	export function SectionTitle({
62	  eyebrow,
63	  title,
64	  sub,
65	  align = "center",
66	  className = "",
67	}: {
68	  eyebrow?: string;
69	  title: React.ReactNode;
70	  sub?: React.ReactNode;
71	  align?: "center" | "left";
72	  className?: string;
73	}) {
74	  const alignCls = align === "center" ? "mx-auto text-center" : "text-left";
75	  return (
76	    <div className={`max-w-2xl ${alignCls} ${className}`}>
77	      {eyebrow && <Eyebrow>{eyebrow}</Eyebrow>}
78	      <h2 className="mt-3 text-3xl font-bold tracking-tight text-[var(--fg)] sm:text-4xl text-balance">{title}</h2>
79	      {sub && <p className="mt-4 text-lg leading-relaxed text-[var(--fg-muted)]">{sub}</p>}
80	    </div>
81	  );
82	}
83	
84	type Cta = { label: string; href: string };
85	
86	/**
87	 * Standard sub-page hero. Left-aligned title/sub/CTAs with an optional visual on
88	 * the right; falls back to centered when no visual is supplied. Renders the
89	 * reusable `.hero-aura` glow behind everything.
90	 */
91	export function PageHero({
92	  eyebrow,
93	  title,
94	  highlight,
95	  sub,
96	  primary,
97	  secondary,
98	  visual,
99	  logo,
100	  children,
101	}: {
102	  eyebrow?: string;
103	  title: React.ReactNode;
104	  /** Optional trailing fragment rendered in the brand gradient. */
105	  highlight?: string;
106	  sub?: React.ReactNode;
107	  primary?: Cta;
108	  secondary?: Cta;
109	  visual?: React.ReactNode;
110	  /** Optional brand mark (e.g. <GameLogo>) shown above the eyebrow. */
111	  logo?: React.ReactNode;
112	  children?: React.ReactNode;
113	}) {
114	  const centered = !visual;
115	  return (
116	    <section className="relative overflow-hidden">
117	      <div className="pointer-events-none absolute inset-0 -z-10 hero-aura" aria-hidden />
118	      <div className="rail py-20 sm:py-28">
119	        <div className={centered ? "mx-auto max-w-3xl text-center" : "grid items-center gap-12 lg:grid-cols-2"}>
120	          <Reveal>
121	            {logo && <div className={`mb-5 flex ${centered ? "justify-center" : ""}`}>{logo}</div>}
122	            {eyebrow && <Eyebrow pill>{eyebrow}</Eyebrow>}
123	            <h1 className="mt-5 text-4xl font-bold leading-[1.08] tracking-tight text-white sm:text-5xl lg:text-6xl text-balance">
124	              {title}
125	              {highlight && (
126	                <>
127	                  {" "}
128	                  <span className="grad-text">{highlight}</span>
129	                </>
130	              )}
131	            </h1>
132	            {sub && (
133	              <p className={`mt-6 text-lg leading-relaxed text-slate-400 sm:text-xl ${centered ? "mx-auto max-w-2xl" : "max-w-xl"}`}>
134	                {sub}
135	              </p>
136	            )}
137	            {(primary || secondary) && (
138	              <div className={`mt-9 flex flex-wrap gap-3 ${centered ? "justify-center" : ""}`}>
139	                {primary && (
140	                  <Link href={primary.href} className="btn-deploy px-5 py-3 text-base">
141	                    {primary.label}
142	                    <span className="dep-arrow" aria-hidden>→</span>
143	                  </Link>
144	                )}
145	                {secondary && (
146	                  <Link href={secondary.href} className="btn-secondary px-5 py-3 text-base">
147	                    {secondary.label}
148	                  </Link>
149	                )}
150	              </div>
151	            )}
152	            {children}
153	          </Reveal>
154	          {visual && <Reveal className="lg:pl-6">{visual}</Reveal>}
155	        </div>
156	      </div>
157	    </section>
158	  );
159	}
