import Link from "next/link";
import { db } from "@/lib/db";
import { annualDiscountPct } from "@/lib/annual-discount";
import { Section, SectionTitle, Eyebrow } from "./primitives";
import { CtaBand } from "./sections";
import { Reveal } from "./Reveal";
import { FaqJsonLd } from "./StructuredData";
import { AmbientField } from "./AmbientField";
import { PricingGrid } from "./PricingGrid";
import { CompetitorLogo } from "./CompetitorLogo";
import {
  IconServer,
  IconBolt,
  IconApps,
  IconCheck,
  IconArrow,
  IconScale,
} from "./icons";

export type MigrateFaq = { q: string; a: string };

/**
 * One shared layout for every "move from X to Nxeon" migration-intent page, so
 * all ten read as a single premium, honest thing — distinct from the
 * `ComparePageLayout` used by the `/vps-vs-X` comparison pages. Where those
 * lead with a feature-by-feature table for "X vs Y" shoppers, this layout leads
 * with the migration STORY for people who already decided to leave and are
 * searching "move from X to Nxeon" / "migrate from X".
 *
 * Section order:
 *   1. Hero — {provider} → Nxeon lockup, "Move from {provider} to Nxeon" + CTA
 *   2. The real four-step migration story (same mechanics as /migrate,
 *      personalised with the provider's name — never invented steps)
 *   3. "Why people move from {provider}" — honest, generic, per-provider bullets
 *   4. Real, DB-fed Nxeon plan pricing (displayed === charged; no hard-coded price)
 *   5. FAQ (defaults answer from the real mechanics; a page can override) → FaqJsonLd
 *   6. Closing CtaBand to /dashboard/migrate
 *
 * Each `app/(marketing)/migrate-from-*/page.tsx` stays a thin data file: it
 * passes the provider's display name/slug, its own `Metadata`, and 3-4 honest
 * "why people leave" bullets. This layout owns the markup and reads the live
 * plan catalogue itself, so no Nxeon price is ever hardcoded here either.
 */

/** The real four-beat migration story from /migrate, personalised per provider. */
function migrationSteps(provider: string) {
  return [
    {
      icon: <IconServer size={20} />,
      title: `Connect your ${provider} server`,
      body: "Point us at it with its SSH details. That's the whole setup — no agent to install, and we never store your credentials.",
    },
    {
      icon: <IconBolt size={20} />,
      title: "We scan & detect everything",
      body: "A read-only scan finds your files, home dirs, databases, Docker containers and running apps — with sizes — so nothing gets left behind.",
    },
    {
      icon: <IconApps size={20} />,
      title: "One click to migrate",
      body: "We install the prerequisites, copy everything to the same paths, import your databases, and bring your containers and services up.",
    },
    {
      icon: <IconCheck size={20} />,
      title: "Live on Nxeon",
      body: `We verify what's actually running and hand you a clear list of anything that needs a manual touch. Your ${provider} server never changes.`,
    },
  ];
}

/** Honest defaults, sourced from the real /migrate mechanics — never invented. */
function defaultFaq(provider: string): MigrateFaq[] {
  return [
    {
      q: "Will my site go down during the move?",
      a: `No. The scan and the copy are strictly read-only on your ${provider} server — we only read your files and dump your databases. Nothing there is changed, stopped, or deleted, and it keeps serving traffic the whole time. Your site only cuts over when you're happy and point your DNS at Nxeon.`,
    },
    {
      q: `Do I need to give you my ${provider} account password?`,
      a: `No. We never ask for your ${provider} account or control-panel login. What we need is SSH access to the server itself, and we don't store those credentials either. Database migration doesn't need a password at all — we dump MySQL, MariaDB and PostgreSQL using root over the source's local socket.`,
    },
    {
      q: "What if something doesn't migrate cleanly?",
      a: "We're honest here: we start everything we can — files, databases, Docker Compose stacks, services — and then verify what's actually running. Anything unusual, like a hand-built systemd unit, a one-off container, or a different-CPU-architecture binary, is listed clearly so you know the exact remaining step, or our team can take it from there.",
    },
    {
      q: `Is moving from ${provider} really free?`,
      a: "Yes. Migration is free, with no per-gigabyte fee and no migration surcharge — you only pay for the Nxeon server you keep running afterward, and you can run the migration as many times as you need before you cut over.",
    },
  ];
}

export async function MigrateFromPageLayout({
  provider,
  providerSlug,
  heroSub,
  reasons,
  faq,
}: {
  /** Provider display name, e.g. "Hostinger" — must match the /vps-vs-X page's `competitor`. */
  provider: string;
  /** Brand slug for the hero logo — must match the /vps-vs-X page's `competitorSlug`. */
  providerSlug: string;
  /** Optional hero value prop; a sensible provider-aware default is used otherwise. */
  heroSub?: string;
  /** 3-4 honest, generic "why people leave {provider}" bullets — no invented stats. */
  reasons: string[];
  /** 2-4 Q/A pairs; defaults to the real /migrate mechanics, personalised. */
  faq?: MigrateFaq[];
}) {
  // Live catalogue — the same plan records and annual rate the /vps lander and
  // checkout use, so every price shown here is DB-fed, not a literal.
  const [plans, annualPct] = await Promise.all([
    db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
    annualDiscountPct(),
  ]);

  const steps = migrationSteps(provider);
  const faqItems = faq ?? defaultFaq(provider);
  const sub =
    heroSub ??
    `Already on ${provider}? Point us at it and we'll scan it, detect your whole stack, and bring it up running on Nxeon — same paths, no downtime on your ${provider} server, and it's free.`;

  return (
    <div className="relative overflow-hidden">
      <FaqJsonLd items={faqItems} />

      {/* Ambient cursor-reactive node field — the site signature. */}
      <div aria-hidden className="pointer-events-none absolute inset-0 z-0">
        <AmbientField />
        <div className="absolute inset-0 bg-[radial-gradient(ellipse_70%_50%_at_20%_-5%,rgba(111,71,245,0.16),transparent_60%),radial-gradient(ellipse_60%_40%_at_90%_0%,rgba(59,130,246,0.12),transparent_60%)]" />
      </div>

      <div className="relative z-10">
        {/* ── 1 · Hero: {provider} → Nxeon ──────────────────────────────── */}
        <section className="relative overflow-hidden">
          <div className="pointer-events-none absolute inset-0 -z-10 hero-aura" aria-hidden />
          <div className="rail py-20 text-center sm:py-24">
            <Reveal>
              <Eyebrow pill>Free migration</Eyebrow>

              {/* {Provider} → Nxeon */}
              <div className="mt-8 flex items-center justify-center gap-5 sm:gap-8">
                <div className="flex h-16 items-center justify-center rounded-2xl border border-white/[0.10] bg-navy-900/70 px-5 backdrop-blur-md sm:h-20 sm:px-7">
                  <CompetitorLogo slug={providerSlug} name={provider} size={34} />
                </div>
                <span className="text-brand-300" aria-hidden>
                  <IconArrow size={22} />
                </span>
                <div className="flex h-16 items-center justify-center rounded-2xl border border-white/[0.10] bg-navy-900/70 px-5 backdrop-blur-md sm:h-20 sm:px-7">
                  <CompetitorLogo slug="nxeon" name="Nxeon" size={34} />
                </div>
              </div>

              <h1 className="mx-auto mt-8 max-w-3xl text-4xl font-bold leading-[1.08] tracking-tight text-white sm:text-5xl lg:text-6xl text-balance">
                Move from {provider} <span className="grad-text">to Nxeon</span>
              </h1>
              <p className="mx-auto mt-6 max-w-2xl text-lg leading-relaxed text-slate-400 sm:text-xl">
                {sub}
              </p>

              <div className="mt-9 flex flex-wrap justify-center gap-3">
                <Link href="/dashboard/migrate" className="btn-deploy px-5 py-3 text-base">
                  Migrate free
                  <span className="dep-arrow" aria-hidden>→</span>
                </Link>
                <Link href={`/vps-vs-${providerSlug}`} className="btn-secondary px-5 py-3 text-base">
                  Compare Nxeon vs {provider}
                </Link>
              </div>

              <ul className="mt-9 flex flex-wrap justify-center gap-x-5 gap-y-2">
                {["Free migration", `No downtime on your ${provider} server`, "No DB passwords needed"].map((t) => (
                  <li key={t} className="inline-flex items-center gap-2 text-sm text-slate-400">
                    <span className="flex h-4.5 w-4.5 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-400">
                      <IconCheck size={12} />
                    </span>
                    {t}
                  </li>
                ))}
              </ul>
            </Reveal>
          </div>
        </section>

        {/* ── 2 · The real migration story ────────────────────────────────── */}
        <Section tone="panel" size="lg">
          <SectionTitle
            eyebrow="How it works"
            title={`From ${provider} to live on Nxeon`}
            sub="Four beats, and only the first one needs you. Connect once, then watch the scan, the click, and the bring-up happen."
          />
          <div className="mt-12 grid gap-5 sm:grid-cols-2 lg:grid-cols-4">
            {steps.map((s, i) => (
              <Reveal key={s.title} delay={i * 80} className="card lift h-full">
