            {reasons.map((r, i) => (
              <Reveal key={r} delay={(i % 4) * 60} className="card flex items-start gap-3">
                <span className="mt-0.5 flex h-8 w-8 flex-none items-center justify-center rounded-full bg-amber-500/15 text-amber-400">
                  <IconScale size={16} />
                </span>
                <p className="text-sm leading-relaxed text-slate-300">{r}</p>
              </Reveal>
            ))}
          </div>
        </Section>

        {/* ── 4 · Real, DB-fed pricing ─────────────────────────────────────── */}
        <Section tone="deep" size="lg">
          <SectionTitle
            eyebrow="Pricing"
            title="Simple, all-in Nxeon plans"
            sub="The price you see is the price checkout charges — read live from our catalogue. Every tier gets the same platform, root access and protection; you only choose the horsepower."
          />
          <div className="mt-12">
            <PricingGrid plans={plans} annualPct={annualPct} />
          </div>
        </Section>

        {/* ── 5 · FAQ ───────────────────────────────────────────────────────── */}
        <Section tone="panel" size="lg">
          <SectionTitle eyebrow="FAQ" title="The questions everyone asks before switching" />
          <div className="mx-auto mt-12 grid max-w-4xl gap-4 sm:grid-cols-2">
            {faqItems.map((f, i) => (
              <Reveal key={f.q} delay={(i % 2) * 60} className="card h-full">
                <h3 className="text-base font-semibold text-white">{f.q}</h3>
                <p className="mt-2 text-sm leading-relaxed text-slate-400">{f.a}</p>
              </Reveal>
            ))}
          </div>
        </Section>

        {/* ── 6 · Final CTA ─────────────────────────────────────────────────── */}
        <Section tone="base" size="lg">
          <CtaBand
            title={
              <>
                Stop putting off the move. <span className="grad-text">Bring it all over in one click.</span>
              </>
            }
            sub={`Migration off ${provider} is free and your old server keeps running the whole time. Connect it, scan it, and see your whole stack come up on Nxeon.`}
            primary={{ label: "Migrate free", href: "/dashboard/migrate" }}
            secondary={{ label: "Create an account", href: "/register" }}
          />
        </Section>
      </div>
    </div>
  );
}

